svg.script:
(function(){
  var svg=document.currentScript.parentNode;
  function set(reg){
    svg.querySelectorAll('.part.is-on').forEach(function(p){p.classList.remove('is-on');});
    if(!reg){ svg.removeAttribute('data-active'); return; }
    svg.setAttribute('data-active',reg);
    svg.querySelectorAll('[data-region="'+reg+'"]').forEach(function(p){p.classList.add('is-on');});
  }
  svg.addEventListener('click',function(e){
    var p=e.target.closest('[data-region]');
    if(!p){ set(null); return; }
    set(p.getAttribute('data-region'));
    svg.dispatchEvent(new CustomEvent('brainpartselect',{bubbles:true,detail:{
      region:p.getAttribute('data-region'), part:p.getAttribute('data-part'),
      id:p.id, label:p.getAttribute('data-label')}}));
  });
  svg.selectRegion=set;
})();
